package com.elogistic.backend.workflow.internal.web;

import com.elogistic.backend.merchant.api.customer.MerchantFacilities;
import com.elogistic.backend.merchant.api.customer.MerchantFacilities.*;
import com.elogistic.backend.orders.api.BusinessPreparations;
import jakarta.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.net.URI;
import java.util.*;
import java.util.function.Function;
import org.springframework.context.annotation.Profile;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import tools.jackson.core.StreamReadFeature;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import static com.elogistic.backend.workflow.internal.web.BusinessPreparationHttp.*;
import static com.elogistic.backend.workflow.internal.web.CustomerProfileHttp.problem;

@RestController @Profile("customer")
public final class MerchantFacilitiesHttp {
    private static final String BASE="/api/v1/merchant-organizations/{organizationId}";
    private static final JsonMapper JSON=JsonMapper.builder().enable(StreamReadFeature.STRICT_DUPLICATE_DETECTION).build();
    private final BusinessPreparationHttp admission;private final MerchantFacilities facilities;
    public MerchantFacilitiesHttp(BusinessPreparationHttp admission,MerchantFacilities facilities){this.admission=admission;this.facilities=facilities;}
    @ModelAttribute public void noStore(jakarta.servlet.http.HttpServletResponse response){response.setHeader("Cache-Control","no-store");}
    private static Access access(BusinessPreparations.Access a){return new Access(){public UUID actorAccountId(){return a.actorAccountId();}public UUID requestId(){return a.requestId();}public com.elogistic.backend.merchant.api.customer.BusinessWorkspaces.Scope scope(){return a.scope();}public void requireCurrent(){a.requireCurrent();}public void meaningfulAction(){a.meaningfulAction();}};}
    private <T>T execute(String org,Set<UUID> subjects,Function<Access,T> work){try{return admission.executeWithContext(org,subjects,(a,c)->work.apply(access(a)));}catch(MerchantFacilities.Failure e){throw problem(switch(e.getMessage()){case "VALIDATION_FAILED"->400;case "RESOURCE_NOT_FOUND"->404;case "PRECONDITION_STALE","IDEMPOTENCY_CONFLICT","FACILITY_CODE_CONFLICT","FACILITY_CODE_IMMUTABLE","FACILITY_STATE_CONFLICT","FACILITY_REFERENCED","FACILITY_MEMBER_UNAVAILABLE"->409;default->503;},e.getMessage());}}
    private <T>T execute(String org,Function<Access,T> work){return execute(org,Set.of(),work);}
    private static Map<String,String> params(HttpServletRequest r,Set<String> allowed){var p=new HashMap<String,String>();r.getParameterMap().forEach((k,v)->{if(!allowed.contains(k)||v.length!=1)throw problem(400,"VALIDATION_FAILED");p.put(k,v[0]);});return p;}
    private static JsonNode body(HttpServletRequest r)throws IOException{if(r.getContentType()==null||!r.getContentType().split(";",2)[0].equalsIgnoreCase("application/json"))throw problem(400,"VALIDATION_FAILED");byte[] bytes=r.getInputStream().readNBytes(16385);try{if(bytes.length>16384)throw problem(400,"VALIDATION_FAILED");return JSON.readTree(bytes);}catch(RuntimeException e){throw problem(400,"VALIDATION_FAILED");}finally{Arrays.fill(bytes,(byte)0);}}
    private static String text(JsonNode v,String k){var n=v.get(k);if(n==null||!n.isString())throw problem(400,"VALIDATION_FAILED");return n.asString();}
    private static void contact(JsonNode c){shape(c,Set.of("name","phone","address"),Set.of("name","phone","address"));text(c,"name");text(c,"phone");var a=c.get("address");var fields=Set.of("country","administrativeArea","locality","addressLine");shape(a,fields,fields);for(String k:fields)text(a,k);}
    private static Input input(JsonNode v){var fields=Set.of("name","code","kind","contact","senderContact","returnContact","operatingHours");shape(v,fields,fields);for(String k:List.of("name","code","kind"))text(v,k);contact(v.get("contact"));for(String k:List.of("senderContact","returnContact"))if(!v.get(k).isNull())contact(v.get(k));var h=v.get("operatingHours");if(!h.isNull()){shape(h,Set.of("timeZone","days"),Set.of("timeZone","days"));text(h,"timeZone");var days=h.get("days");if(!days.isArray()||days.size()!=7)throw problem(400,"VALIDATION_FAILED");for(var d:days){shape(d,Set.of("day","intervals"),Set.of("day","intervals"));text(d,"day");var intervals=d.get("intervals");if(!intervals.isArray()||intervals.size()>2)throw problem(400,"VALIDATION_FAILED");for(var i:intervals){shape(i,Set.of("opensAt","closesAt"),Set.of("opensAt","closesAt"));text(i,"opensAt");text(i,"closesAt");}}}try{return JSON.treeToValue(v,Input.class);}catch(RuntimeException e){throw problem(400,"VALIDATION_FAILED");}}
    private static Query query(Map<String,String> p,String search){return new Query(number(p.get("page"),0),number(p.get("size"),20),p.get("state"),p.get("kind"),p.get("code"),search);}
    private static ResponseEntity<Facility> response(Facility f){return ResponseEntity.ok().eTag("\"v"+f.version()+"\"").body(f);}
    @GetMapping(BASE+"/facilities") public Page list(@PathVariable String organizationId,HttpServletRequest r){var q=query(params(r,Set.of("page","size","state","kind","code")),null);return execute(organizationId,a->facilities.list(a,q));}
    @PostMapping(BASE+"/facilities/search") public Page search(@PathVariable String organizationId,HttpServletRequest r)throws IOException{params(r,Set.of());var v=body(r);shape(v,Set.of("page","size","search"),Set.of("page","size","search","state","kind"));var p=new HashMap<String,String>();for(String k:List.of("page","size")){if(!v.get(k).isIntegralNumber()||!v.get(k).canConvertToInt())throw problem(400,"VALIDATION_FAILED");p.put(k,Integer.toString(v.get(k).asInt()));}for(String k:List.of("state","kind"))if(v.has(k))p.put(k,text(v,k));var q=query(p,text(v,"search"));return execute(organizationId,a->facilities.list(a,q));}
    @PostMapping(BASE+"/facilities") public ResponseEntity<Facility> create(@PathVariable String organizationId,HttpServletRequest r)throws IOException{params(r,Set.of());UUID key=key(r);var in=input(body(r));var f=execute(organizationId,a->facilities.create(a,in,key));return ResponseEntity.created(URI.create("/api/v1/merchant-organizations/"+f.organizationId()+"/facilities/"+f.id())).eTag("\"v"+f.version()+"\"").body(f);}
    @GetMapping(BASE+"/facilities/{id}") public ResponseEntity<Facility> get(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r){params(r,Set.of());UUID target=uuid(id);return response(execute(organizationId,a->facilities.get(a,target)));}
    @PutMapping(BASE+"/facilities/{id}") public ResponseEntity<Facility> update(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r)throws IOException{params(r,Set.of());UUID target=uuid(id),key=key(r);long v=version(r);var in=input(body(r));return response(execute(organizationId,a->facilities.update(a,target,in,v,key)));}
    @PostMapping(BASE+"/facilities/{id}/archive") public ResponseEntity<Facility> archive(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r)throws IOException{params(r,Set.of());UUID target=uuid(id),key=key(r);long v=version(r);if(r.getInputStream().read()!=-1)throw problem(400,"VALIDATION_FAILED");return response(execute(organizationId,a->facilities.archive(a,target,v,key)));}
    private static long bindingVersion(HttpServletRequest r,String prefix){var h=Collections.list(r.getHeaders("If-Match"));if(h.isEmpty())throw problem(428,"PRECONDITION_REQUIRED");try{if(h.size()!=1||!h.getFirst().matches("\""+prefix+"(?:0|[1-9][0-9]{0,18})\""))throw new IllegalArgumentException();return Long.parseLong(h.getFirst().substring(2,h.getFirst().length()-1));}catch(RuntimeException e){throw problem(400,"VALIDATION_FAILED");}}
    @GetMapping(BASE+"/facility-default") public ResponseEntity<Default> defaultFacility(@PathVariable String organizationId,HttpServletRequest r){params(r,Set.of());var d=execute(organizationId,facilities::defaultFacility);return ResponseEntity.ok().eTag("\"d"+d.version()+"\"").body(d);}
    @PutMapping(BASE+"/facility-default") public ResponseEntity<Default> setDefault(@PathVariable String organizationId,HttpServletRequest r)throws IOException{params(r,Set.of());UUID key=key(r);long version=bindingVersion(r,"d");var v=body(r);shape(v,Set.of("facilityId"),Set.of("facilityId"));UUID site=v.get("facilityId").isNull()?null:uuid(text(v,"facilityId"));var d=execute(organizationId,a->facilities.setDefault(a,site,version,key));return ResponseEntity.ok().eTag("\"d"+d.version()+"\"").body(d);}
    @GetMapping(BASE+"/facilities/{id}/responsibilities") public ResponseEntity<Responsibilities> responsibilities(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r){params(r,Set.of());var d=execute(organizationId,a->facilities.responsibilities(a,uuid(id)));return ResponseEntity.ok().eTag("\"v"+d.version()+"\"").body(d);}
    @PutMapping(BASE+"/facilities/{id}/responsibilities") public ResponseEntity<Responsibilities> team(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r)throws IOException{params(r,Set.of());UUID target=uuid(id),key=key(r);long expected=bindingVersion(r,"v");var v=body(r);shape(v,Set.of("items"),Set.of("items"));var items=v.get("items");if(!items.isArray()||items.size()>30)throw problem(400,"VALIDATION_FAILED");var list=new ArrayList<Responsibility>();var references=new HashSet<UUID>();for(var i:items){shape(i,Set.of("accountId","responsibility"),Set.of("accountId","responsibility"));UUID account=uuid(text(i,"accountId"));references.add(account);list.add(new Responsibility(account,text(i,"responsibility")));}var d=execute(organizationId,references,a->facilities.setResponsibilities(a,target,list,expected,key));return ResponseEntity.ok().eTag("\"v"+d.version()+"\"").body(d);}
    @GetMapping(BASE+"/facilities/{id}/members") public Map<String,Object> members(@PathVariable String organizationId,@PathVariable String id,HttpServletRequest r){var p=params(r,Set.of("page","size"));int page=number(p.get("page"),0);if(number(p.get("size"),20)!=20)throw problem(400,"VALIDATION_FAILED");UUID site=uuid(id);var discovered=execute(organizationId,a->{facilities.get(a,site);return a.scope().facilityMembers(site,page);});Set<UUID> references=new HashSet<>();discovered.forEach(m->references.add(m.accountId()));return admission.executeWithContext(organizationId,references,(a,c)->{facilities.get(access(a),site);var rows=a.scope().facilityMembers(site,page);var selected=rows.stream().limit(20).filter(m->a.scope().eligibleFacilityMember(m.accountId(),site)).map(m->Map.of("accountId",m.accountId(),"membershipId",m.membershipId(),"role",m.role(),"displayName",c.subjects().get(m.accountId()).displayName())).toList();return Map.of("items",selected,"page",page,"size",20,"hasNext",rows.size()>20);});}
    @GetMapping(BASE+"/facility-receipts/{operation}/{key}") public Receipt receipt(@PathVariable String organizationId,@PathVariable String operation,@PathVariable String key,HttpServletRequest r){params(r,Set.of());return execute(organizationId,a->facilities.receipt(a,operation,uuid(key)));}
}
